// 03 · Normalize — read original webhook (Set node must not wipe body)
const webhook = $('01 · Receive Order Webhook').item.json;
const body = webhook.body ?? webhook;
const loc =
  $('02 · Set GHL Location ID').item.json.locationId ||
  'uc3GK4buCjDTCkedqWyy';

const customer = body.customer || {};
const order = body.order || {};
const phone = (
  customer.phone_e164 ||
  customer.phone ||
  customer.phone_raw ||
  ''
)
  .toString()
  .trim();
const rawName = (customer.name || '').toString().trim();
const firstName = rawName.split(/\s+/)[0] || 'Guest';
const lastName = rawName.split(/\s+/).slice(1).join(' ') || 'Caller';

const orderType = (order.order_type || '').toString().toLowerCase();
const channel = (body.channel || '').toString().toLowerCase() || null;
const status = (order.status || 'placed').toString().toLowerCase();
const lastOrderId =
  order.clover_order_id || body.session_id || body.event_id || null;
const total = order.total ?? null;

const items = Array.isArray(order.items) ? order.items : [];
const summary =
  items.length > 0
    ? items
        .map((i) => {
          const qty = i.qty ?? i.quantity ?? 1;
          const name = i.name || 'item';
          return `${qty}x ${name}`;
        })
        .join(', ')
    : null;

const tagsToAdd = ['voice-order', 'order-placed'];
if (orderType === 'pickup') tagsToAdd.push('pickup');
if (orderType === 'delivery') tagsToAdd.push('delivery');

// Contact custom field IDs — plan §7.1
const customFields = [
  { id: '0QK5vxB5ntrYG44o33Gn', field_value: lastOrderId != null ? String(lastOrderId) : '' },
  { id: 'nl3jIwfxyUgQHPRlbGZl', field_value: orderType || '' },
  { id: 'Q59Rb7F84BNHvrL1gzOJ', field_value: status || 'placed' },
  {
    id: 'IeLzeT4I8xitx3Jvk9mQ',
    field_value: total != null && total !== '' ? Number(total) : '',
  },
  { id: 'FyLZbBVUDD9TzY7LXlm4', field_value: summary || '' },
  { id: 'UUqkRGbEl5HjS5Sd2eIz', field_value: channel || '' },
].filter((f) => f.field_value !== '' && f.field_value !== null && f.field_value !== undefined);

const upsertBody = {
  locationId: loc,
  phone,
  firstName,
  lastName,
  source: 'Voice Agent',
  customFields,
};

return {
  json: {
    locationId: loc,
    event: body.event || 'unknown',
    event_id: body.event_id || null,
    session_id: body.session_id || null,
    channel,
    phone,
    firstName,
    lastName,
    fullName: rawName || null,
    order_type: orderType || null,
    clover_order_id: order.clover_order_id || null,
    order_total: total,
    order_summary: summary,
    tagsToAdd,
    upsertBody,
    hasPhone: phone.length >= 7,
    raw: body,
  },
};

// 08 · Prepare opportunity payload — plan §7.2
const norm = $('03 · Normalize Order Payload').item.json;
const upsert = $('05 · GHL · Upsert Contact + Fields').item.json;
const contactId = upsert.contact?.id || null;

const PIPELINE_ID = 'wCQVOwUah69xD6KHFrsi';
const STAGE_ABANDONED = 'ed4e4d7b-7a77-4e86-9c98-5a4204a046ac';
const STAGE_PLACED = 'a6c71988-47c0-4f13-8a2b-40b784a9a72f';
const CF_EVENT_ID = 'ebYtqePmkjxB2BFjaEtJ';
const CF_CLOVER = 'mqQZGfXEM7Ixbfcpbeej';
const CF_SESSION = 'urTkDJuILkxhG4942CmU';
const CF_SUMMARY = 'zH1m3iD6sNuy8y22uqMa';

const typePart = norm.order_type || 'order';
const namePart = norm.firstName || 'Guest';
const summaryPart = (norm.order_summary || '').toString();
let oppName = `${typePart} · ${namePart}`;
if (summaryPart) oppName += ` · ${summaryPart}`;
if (oppName.length > 80) oppName = oppName.slice(0, 77) + '...';

const oppCustomFields = [
  { id: CF_EVENT_ID, field_value: norm.event_id != null ? String(norm.event_id) : '' },
  { id: CF_CLOVER, field_value: norm.clover_order_id != null ? String(norm.clover_order_id) : '' },
  { id: CF_SESSION, field_value: norm.session_id != null ? String(norm.session_id) : '' },
  { id: CF_SUMMARY, field_value: summaryPart },
].filter((f) => f.field_value !== '' && f.field_value !== null && f.field_value !== undefined);

const monetary =
  norm.order_total != null && norm.order_total !== ''
    ? Number(norm.order_total)
    : undefined;

const createBody = {
  pipelineId: PIPELINE_ID,
  locationId: norm.locationId,
  name: oppName,
  pipelineStageId: STAGE_PLACED,
  status: 'open',
  contactId,
  customFields: oppCustomFields,
};
if (monetary != null && !Number.isNaN(monetary)) {
  createBody.monetaryValue = monetary;
}

const updateBody = {
  name: oppName,
  pipelineId: PIPELINE_ID,
  pipelineStageId: STAGE_PLACED,
  status: 'open',
  customFields: oppCustomFields,
};
if (monetary != null && !Number.isNaN(monetary)) {
  updateBody.monetaryValue = monetary;
}

return {
  json: {
    contactId,
    session_id: norm.session_id || null,
    pipelineId: PIPELINE_ID,
    stageAbandonedId: STAGE_ABANDONED,
    stagePlacedId: STAGE_PLACED,
    locationId: norm.locationId,
    createBody,
    updateBody,
    skipOpp: !contactId,
  },
};

// 10 · Resolve create vs move Abandoned→Placed
const prep = $('08 · Prepare Opportunity').item.json;
const search = $input.item.json;
const sessionId = prep.session_id ? String(prep.session_id) : null;
const CF_SESSION = 'urTkDJuILkxhG4942CmU';

const list = search.opportunities || search.data?.opportunities || [];
let matchId = null;
if (sessionId && Array.isArray(list)) {
  for (const opp of list) {
    const cfs = opp.customFields || opp.customField || [];
    const hit = cfs.find(
      (c) =>
        (c.id === CF_SESSION || c.fieldKey === 'opportunity.session_id' || c.key === 'opportunity.session_id') &&
        String(c.fieldValue ?? c.field_value ?? c.value ?? '') === sessionId
    );
    if (hit) {
      matchId = opp.id;
      break;
    }
  }
}

const moveExisting = Boolean(matchId) && !prep.skipOpp;
const createNew = !moveExisting && !prep.skipOpp;

return {
  json: {
    ...prep,
    matchOpportunityId: matchId,
    moveExisting,
    createNew,
    searchCount: Array.isArray(list) ? list.length : 0,
  },
};

const norm = $('03 · Normalize Order Payload').first().json;
const upsert = $('05 · GHL · Upsert Contact + Fields').first().json;
const resolve = $('10 · Resolve Opp Action').first().json;
const oppResp = $input.first().json;
const status = upsert.statusCode ?? upsert.status ?? null;
const contactId = upsert.contact?.id || upsert.body?.contact?.id || null;

const opp =
  oppResp.opportunity ||
  oppResp.body?.opportunity ||
  oppResp.data?.opportunity ||
  oppResp;
const oppId = opp?.id || resolve.matchOpportunityId || null;
const oppHttp = oppResp.statusCode ?? oppResp.status ?? null;
const sideEffectOk = Boolean(contactId && oppId);

return {
  json: {
    ok: sideEffectOk,
    side_effect_ok: sideEffectOk,
    event: norm.event,
    event_id: norm.event_id,
    phone: norm.phone,
    tags: norm.tagsToAdd,
    order_summary: norm.order_summary,
    ghl_http_status: status,
    ghl_ok: Boolean(contactId),
    ghl_contact_id: contactId,
    sms_rearm: 'removed order-placed then re-added',
    opp_action: resolve.moveExisting ? 'moved_abandoned_to_placed' : resolve.createNew ? 'created_placed' : 'skipped',
    opp_id: oppId,
    opp_http_status: oppHttp,
    error: sideEffectOk ? null : 'order_placed_ghl_side_effect_failed',
  },
};

const webhook = $('01 · Receive Order Webhook').item.json;
const body = webhook.body ?? webhook;
const customer = body.customer || {};
const order = body.order || {};
const meta = body.meta || {};
const event = String(body.event || '').trim();
const eventId = String(body.event_id || '').trim();
const schemaVersion = Number(body.schema_version || 0);
const phone = String(customer.phone_e164 || customer.phone || '').trim();
const name = String(customer.name || 'Guest').trim() || 'Guest';
const firstName = name.split(/\s+/)[0] || 'Guest';
const lastName = name.split(/\s+/).slice(1).join(' ') || 'Customer';
const locationId = 'uc3GK4buCjDTCkedqWyy';
const cloverOrderId = String(order.clover_order_id || '').trim();
const receiptUrl = String(order.receipt_url || '').trim();
const trackingUrl = String(order.tracking_url || '').trim();
const uberDeliveryId = String(order.uber_delivery_id || '').trim();
const deliveryStatus = String(order.delivery_status || order.status || '').trim().toLowerCase();
const previousDeliveryStatus = String(meta.previous_status || '').trim().toLowerCase();
const customerMilestone = String(meta.customer_milestone || '').trim().toLowerCase();
const staffPhone = String($vars.BIZBULL_STAFF_ALERT_PHONE || '').trim();
const knownDeliveryStatuses = ['pending', 'pickup', 'shopping_completed', 'pickup_complete', 'dropoff', 'delivered', 'canceled', 'failed', 'returned'];
const errors = [];
if (schemaVersion !== 1) errors.push('unsupported_schema_version');
if (!event) errors.push('missing_event');
if (!eventId) errors.push('missing_event_id');

let customerMessage = null;
if (event === 'order.paid') customerMessage = `Bizbull: Thanks — your online payment is confirmed. Order ${cloverOrderId || 'confirmed'}. Receipt: ${receiptUrl}`;
if (event === 'delivery.dispatched') customerMessage = `Bizbull: your courier has been arranged. Track your delivery: ${trackingUrl}`;

const customerUpsertBody = { locationId, phone, firstName, lastName, source: 'Sierra Store Events' };
const staffUpsertBody = { locationId, phone: staffPhone, firstName: 'Bizbull', lastName: 'Delivery Alert', source: 'Sierra Operations' };
const staffMessage = [
  'URGENT: Bizbull delivery needs manual dispatch.',
  `Order: ${cloverOrderId || 'unknown'}`,
  `Customer: ${name}${phone ? ` ${phone}` : ''}`,
  order.delivery_address ? `Address: ${order.delivery_address}` : null,
  order.dispatch_reason ? `Reason: ${order.dispatch_reason}` : null,
  order.dispatch_uncertain ? 'Uber outcome may be uncertain — verify before creating another courier.' : null,
].filter(Boolean).join('\n');

const statusCustomerMessage = customerMilestone === 'on_the_way'
  ? `Bizbull: your order is on the way. Track your delivery: ${trackingUrl}`
  : customerMilestone === 'delivered'
    ? 'Bizbull: your delivery is complete. Thank you for ordering from Bizbull!'
    : null;
const statusStaffMessage = [
  'URGENT: Bizbull delivery status requires attention.',
  `Order: ${cloverOrderId || 'unknown'}`,
  `Uber status: ${deliveryStatus || 'unknown'}`,
  `Customer: ${name}${phone ? ` ${phone}` : ''}`,
  order.cancellation_reason || order.undeliverable_reason || order.failure_reason
    ? `Reason: ${order.cancellation_reason || order.undeliverable_reason || order.failure_reason}`
    : null,
  trackingUrl ? `Tracking: ${trackingUrl}` : null,
].filter(Boolean).join('\n');
const statusCustomerUpsertBody = {
  locationId,
  phone,
  firstName,
  lastName,
  source: 'Sierra Delivery Events',
  customFields: [{ id: 'Q59Rb7F84BNHvrL1gzOJ', field_value: `delivery.${deliveryStatus}` }],
};
const statusStaffUpsertBody = { locationId, phone: staffPhone, firstName: 'Bizbull', lastName: 'Delivery Alert', source: 'Sierra Operations' };
const statusEventValid = event === 'delivery.status_changed'
  && knownDeliveryStatuses.includes(deliveryStatus)
  && Boolean(cloverOrderId)
  && Boolean(uberDeliveryId)
  && phone.length >= 7
  && (!['on_the_way', 'delivered', 'staff_alert'].includes(customerMilestone) || Boolean(statusCustomerMessage || customerMilestone === 'staff_alert'))
  && (customerMilestone !== 'on_the_way' || Boolean(trackingUrl))
  && (customerMilestone !== 'staff_alert' || staffPhone.length >= 7);

return {
  json: {
    body,
    schema_version: schemaVersion,
    event,
    event_id: eventId,
    valid_envelope: errors.length === 0,
    validation_errors: errors,
    locationId,
    phone,
    name,
    clover_order_id: cloverOrderId || null,
    receipt_url: receiptUrl || null,
    tracking_url: trackingUrl || null,
    uber_delivery_id: uberDeliveryId || null,
    delivery_status: deliveryStatus || null,
    previous_delivery_status: previousDeliveryStatus || null,
    customer_milestone: customerMilestone || null,
    has_phone: phone.length >= 7,
    paid_valid: phone.length >= 7 && Boolean(receiptUrl),
    dispatched_valid: phone.length >= 7 && Boolean(trackingUrl),
    status_event_valid: statusEventValid,
    staff_alert_configured: staffPhone.length >= 7,
    customer_message: customerMessage,
    staff_message: staffMessage,
    status_customer_message: statusCustomerMessage,
    status_staff_message: statusStaffMessage,
    customer_upsert_body: customerUpsertBody,
    staff_upsert_body: staffUpsertBody,
    status_customer_upsert_body: statusCustomerUpsertBody,
    status_staff_upsert_body: statusStaffUpsertBody,
    received_at: new Date().toISOString(),
  },
};

const norm = $('P4 · Normalize Envelope').item.json;
const row = $input.item.json || {};
const sameEvent = String(row.event_id || '') === norm.event_id;
const terminalClaim = ['processing', 'completed', 'dead_letter'].includes(String(row.status || ''));
return {
  json: {
    ...norm,
    duplicate: sameEvent && terminalClaim,
    prior_status: sameEvent ? row.status || null : null,
  },
};

const norm = $('P4 · Resolve Duplicate').item.json;
const upsert = $('P4 · Paid · Upsert Customer').item.json;
const sms = $input.item.json;
const contactId = upsert.contact?.id || upsert.body?.contact?.id || null;
const messageId = sms.messageId || sms.body?.messageId || null;
const ok = Boolean(contactId && messageId);
return { json: { ok, side_effect_ok: ok, event: norm.event, event_id: norm.event_id, action: 'receipt_sms', ghl_contact_id: contactId, message_id: messageId, error: ok ? null : 'receipt_sms_failed' } };

const norm = $('P4 · Resolve Duplicate').item.json;
const upsert = $('P4 · Dispatched · Upsert Customer').item.json;
const sms = $input.item.json;
const contactId = upsert.contact?.id || upsert.body?.contact?.id || null;
const messageId = sms.messageId || sms.body?.messageId || null;
const ok = Boolean(contactId && messageId);
return { json: { ok, side_effect_ok: ok, event: norm.event, event_id: norm.event_id, action: 'tracking_sms', ghl_contact_id: contactId, message_id: messageId, error: ok ? null : 'tracking_sms_failed' } };

const norm = $('P4 · Resolve Duplicate').item.json;
const upsert = $('P4 · Alert · Upsert Staff Contact').item.json;
const sms = $input.item.json;
const contactId = upsert.contact?.id || upsert.body?.contact?.id || null;
const messageId = sms.messageId || sms.body?.messageId || null;
const ok = Boolean(contactId && messageId);
return { json: { ok, side_effect_ok: ok, event: norm.event, event_id: norm.event_id, action: 'staff_dispatch_alert', ghl_contact_id: contactId, message_id: messageId, error: ok ? null : 'staff_dispatch_alert_failed' } };

const norm = $('P4 · Resolve Duplicate').item.json;
let reason = 'unsupported_event';
if (norm.event === 'order.paid') reason = 'invalid_paid_event';
if (norm.event === 'delivery.dispatched') reason = 'invalid_dispatched_event';
if (norm.event === 'delivery.status_changed') reason = 'invalid_delivery_status_event';
return { json: { ok: true, side_effect_ok: true, dead_letter: true, event: norm.event, event_id: norm.event_id, action: 'dead_letter', error: reason } };

const input = $input.item.json || {};
const norm = $('P4 · Resolve Duplicate').item.json;
return { json: { ...input, event: input.event || norm.event, event_id: input.event_id || norm.event_id, side_effect_ok: input.side_effect_ok === true } };

const norm = $('P4 · Resolve Duplicate').item.json;
const search = $input.item.json;
const list = search.opportunities || search.body?.opportunities || search.data?.opportunities || [];
const orderFieldId = 'mqQZGfXEM7Ixbfcpbeej';
let matchOpportunityId = null;
for (const opp of Array.isArray(list) ? list : []) {
  const fields = opp.customFields || opp.customField || [];
  const hit = fields.find((field) => (field.id === orderFieldId || field.fieldKey === 'opportunity.clover_order_id' || field.key === 'opportunity.clover_order_id') && String(field.fieldValue ?? field.fieldValueString ?? field.field_value ?? field.value ?? '') === String(norm.clover_order_id));
  if (hit) { matchOpportunityId = opp.id || null; break; }
}
return { json: { ...norm, matchOpportunityId, searchCount: Array.isArray(list) ? list.length : 0 } };

const norm = $('P4 · Resolve Duplicate').item.json;
const upsert = $('P5 · Status · Upsert Customer').item.json;
const moved = $('P5 · Delivered · Move Opportunity → Completed').item.json;
const sms = $input.item.json;
const contactId = upsert.contact?.id || upsert.body?.contact?.id || null;
const opportunityId = moved.opportunity?.id || moved.body?.opportunity?.id || null;
const messageId = sms.messageId || sms.body?.messageId || null;
const ok = Boolean(contactId && opportunityId && messageId);
return { json: { ok, side_effect_ok: ok, event: norm.event, event_id: norm.event_id, action: 'delivery_completed', delivery_status: norm.delivery_status, ghl_contact_id: contactId, opportunity_id: opportunityId, message_id: messageId, error: ok ? null : 'delivery_completed_side_effect_failed' } };

const norm = $('P4 · Resolve Duplicate').item.json;
const upsert = $('P5 · Status · Upsert Customer').item.json;
const sms = $input.item.json;
const contactId = upsert.contact?.id || upsert.body?.contact?.id || null;
const messageId = sms.messageId || sms.body?.messageId || null;
const ok = Boolean(contactId && messageId);
return { json: { ok, side_effect_ok: ok, event: norm.event, event_id: norm.event_id, action: 'delivery_on_the_way_sms', delivery_status: norm.delivery_status, ghl_contact_id: contactId, message_id: messageId, error: ok ? null : 'delivery_on_the_way_sms_failed' } };

const norm = $('P4 · Resolve Duplicate').item.json;
const customerUpsert = $('P5 · Status · Upsert Customer').item.json;
const staffUpsert = $('P5 · Issue · Upsert Staff Contact').item.json;
const sms = $input.item.json;
const customerId = customerUpsert.contact?.id || customerUpsert.body?.contact?.id || null;
const staffId = staffUpsert.contact?.id || staffUpsert.body?.contact?.id || null;
const messageId = sms.messageId || sms.body?.messageId || null;
const ok = Boolean(customerId && staffId && messageId);
return { json: { ok, side_effect_ok: ok, event: norm.event, event_id: norm.event_id, action: 'delivery_issue_staff_alert', delivery_status: norm.delivery_status, ghl_contact_id: customerId, staff_contact_id: staffId, message_id: messageId, error: ok ? null : 'delivery_issue_staff_alert_failed' } };

const norm = $('P4 · Resolve Duplicate').item.json;
const upsert = $('P5 · Status · Upsert Customer').item.json;
const contactId = upsert.contact?.id || upsert.body?.contact?.id || null;
const ok = Boolean(contactId);
return { json: { ok, side_effect_ok: ok, event: norm.event, event_id: norm.event_id, action: 'delivery_status_crm_update', delivery_status: norm.delivery_status, ghl_contact_id: contactId, error: ok ? null : 'delivery_status_crm_update_failed' } };
